        if (!input.new_arrived_at || schoolDateOf(input.new_arrived_at, ctx.tz) !== date2) throw new AppError("VALIDATION_ERROR", "time", { fieldErrors: [{ field: "new_arrived_at", code: "INVALID", message_th: "เวลาใหม่ต้องอยู่ในวันเดียวกัน" }] });
        newEvents.push(cs.insert("AttendanceEvents", { ...base, event_type: "GATE_ARRIVAL", occurred_at: input.new_arrived_at, station_id: arrival.station_id, class_id: arrival.class_id, supersedes_event_id: arrival.id, dedupe_key: `${arrivalDedupeKey(student.id, date2)}|${correctionId}` }));
