        newEvents.push(cs.insert("AttendanceEvents", { ...base, event_type: "GATE_ARRIVAL", occurred_at: input.new_arrived_at, dedupe_key: `${arrivalDedupeKey(student.id, date2)}|${correctionId}` }));
