  function* bootstrapInstallation(deps2, input) {
    const ctx = yield* createContext(deps2, { operation: "setup.bootstrap", channel: "EDITOR" });
    ctx.principal = systemPrincipal(SYSTEM_USER_ID);
    const created = [];
    const cs = ctx.changeSet("setup.bootstrap");
    cs.maintenanceAllowed = true;
    let school2 = (yield ctx.store.list("Schools", { limit: 2 })).items[0];
    if (!school2) {
      school2 = cs.insert("Schools", { code: input.school_code, name_th: input.school_name_th, unit_th: input.unit_th || "กลุ่มบริหารงานกิจการนักเรียน", timezone: "Asia/Bangkok", locale: "th-TH", brand_color: "#B91C1C" });
      created.push("Schools");
    }
    if (!(yield ctx.store.get("Users", SYSTEM_USER_ID))) {
      cs.insert("Users", { id: SYSTEM_USER_ID, school_id: school2.id, user_type: "SYSTEM", display_name: "ระบบ (งานเบื้องหลัง)", status: "ACTIVE" });
      created.push("Users:system");
    }
    let invitationCode = null;
    const admins = yield ctx.store.findBy("UserRoles", "role", "SYSTEM_ADMIN");
    if (!admins.some((r) => !r.revoked_at)) {
      const admin2 = cs.insert("Users", { school_id: school2.id, user_type: "STAFF", display_name: input.admin_display_name, contact_email: input.admin_email, status: "INVITED" });
      cs.insert("UserRoles", { user_id: admin2.id, role: "SYSTEM_ADMIN", effective_from: ctx.today, granted_by: SYSTEM_USER_ID, reason: "bootstrap ผู้ดูแลระบบคนแรก (สิทธิ์งานระบบเท่านั้น)" });
      invitationCode = newInvitationCode(ctx.crypto.randomBytes);
      cs.insert("InvitationRecords", {
        invitation_type: "STAFF",
        target_user_id: admin2.id,
        code_hash: invitationHash(invitationCode),
        bound_email: input.admin_email,
        expires_at: addMinutesIso(ctx.now, 24 * 60),
        max_attempts: 5,
        attempt_count: 0,
        status: "PENDING"
      });
      created.push("Users:bootstrap-admin", "InvitationRecords:bootstrap");
    }
    const rules = (yield ctx.store.list("RuleVersions", { limit: 200 })).items;
    for (const [ruleType, params] of Object.entries(EXAMPLE_RULE_PARAMS)) {
      if (rules.some((r) => r.rule_type === ruleType)) continue;
      cs.insert("RuleVersions", { school_id: school2.id, rule_type: ruleType, version_no: 1, effective_from: input.rule_effective_from, effective_to: null, params_json: params, status: "ACTIVE", is_example: true, notes_th: "ค่าตัวอย่างจากการติดตั้ง — ต้องให้โรงเรียนกำหนดค่าจริงก่อน production" });
      created.push(`RuleVersions:${ruleType}`);
    }
    const settings = (yield ctx.store.list("Settings", { limit: 500 })).items;
    for (const [key, value, desc] of DEFAULT_SETTINGS) {
      if (settings.some((s) => s.key === key)) continue;
      cs.insert("Settings", { school_id: school2.id, key, value_json: value, is_example: true, description_th: desc });
      created.push(`Settings:${key}`);
    }
    if (!cs.isEmpty) {
      cs.audit({ action: "setup.bootstrap", entityType: "Schools", entityId: school2.id, after: { created } });
      yield* commit(ctx, cs, { created });
    }
    return { created, invitation_code: invitationCode, school_id: school2.id };
  }

